// Keep only rows marked Active = TRUE, and compute the search window (last 24h)
const fromDate = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);

return items
  .filter(i => String(i.json.Active).toUpperCase() === 'TRUE')
  .map(i => ({
    json: {
      competitor: i.json.Name,
      query: i.json.SearchQuery || i.json.Name,
      fromDate
    }
  }));

// Flatten each competitor's article list into individual items, cap 5 most recent per competitor, dedupe by URL across the whole run.
const seen = new Set();
const out = [];

for (const item of items) {
  const competitor = item.json.query ? item.json.query : (item.json?.competitor || 'Unknown');
  const articles = (item.json.articles || []).slice(0, 5);
  for (const a of articles) {
    if (!a.url || seen.has(a.url)) continue;
    seen.add(a.url);
    out.push({
      json: {
        competitor,
        title: a.title,
        description: a.description || '',
        url: a.url,
        source: a.source?.name || 'Unknown',
        publishedAt: a.publishedAt
      }
    });
  }
}
return out;

