// Parse the AI's JSON reply and attach summary/category/relevance to each article. Fall back gracefully if parsing fails.
const out = [];
for (const item of items) {
  let parsed = { summary: item.json.description || 'No summary available.', category: 'Other', relevance_score: 5 };
  try {
    const raw = item.json.choices?.[0]?.message?.content || '{}';
    const cleaned = raw.trim().replace(/^```json/, '').replace(/^```/, '').replace(/```$/, '');
    parsed = JSON.parse(cleaned);
  } catch (e) {
    // keep fallback
  }
  out.push({
    json: {
      ...item.json,
      summary: parsed.summary,
      category: parsed.category,
      relevance_score: Number(parsed.relevance_score) || 5
    }
  });
}
return out;

// Optional Extension #3: drop low-relevance noise (e.g. score < 6)
const MIN_RELEVANCE = 6;
return items.filter(i => (i.json.relevance_score || 0) >= MIN_RELEVANCE);

// Aggregate all filtered articles into ONE digest item: group by competitor -> category, build Slack Block Kit + HTML email body.
const byCompetitor = {};
for (const item of items) {
  const c = item.json.competitor;
  byCompetitor[c] = byCompetitor[c] || [];
  byCompetitor[c].push(item.json);
}

const today = new Date().toISOString().slice(0, 10);
let slackBlocks = [
  { type: 'header', text: { type: 'plain_text', text: `🗞️ Competitor Digest — ${today}` } }
];
let html = `<h2>Competitor News Digest — ${today}</h2>`;

const competitors = Object.keys(byCompetitor);
if (competitors.length === 0) {
  slackBlocks.push({ type: 'section', text: { type: 'mrkdwn', text: 'No relevant competitor news today.' } });
  html += '<p>No relevant competitor news today.</p>';
} else {
  for (const c of competitors) {
    slackBlocks.push({ type: 'divider' });
    slackBlocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*${c}*` } });
    html += `<h3>${c}</h3><ul>`;
    for (const a of byCompetitor[c]) {
      slackBlocks.push({
        type: 'section',
        text: { type: 'mrkdwn', text: `• *[${a.category}]* <${a.url}|${a.title}>\n${a.summary}` }
      });
      html += `<li><b>[${a.category}]</b> <a href="${a.url}">${a.title}</a><br>${a.summary}</li>`;
    }
    html += '</ul>';
  }
}

return [{ json: { slackBlocks, htmlBody: html, date: today, articleCount: items.length } }];

// Keep only rows logged in the last 7 days
const sevenDaysAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
return items.filter(i => new Date(i.json.Date).getTime() >= sevenDaysAgo);

